            new Quote { Id = "https://en.wikiquote.org/wiki/Noam_Chomsky", Text = "In brief, it is clear that no present-day theory of language can hope to attain explanatory adequacy beyond very restricted domains.", Author = "Noam Chomsky" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Noam_Chomsky", Text = "In short, the structure of particular languages may very well be largely determined by factors over which the individual has no conscious control and concerning which society may have little choice or freedom.", Author = "Noam Chomsky" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Noam_Chomsky", Text = "The deep structure that expresses the meaning is common to all languages, so it is claimed, being a simple reflection of the forms of thought.", Author = "Noam Chomsky" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Noam_Chomsky", Text = "The central doctrine of Cartesian linguistics is that the general features of grammatical structure are common to all languages and reflect certain fundamental properties of the mind.", Author = "Noam Chomsky" },
