            new Quote { Id = "https://en.wikiquote.org/wiki/Noam_Chomsky", Text = "The war is simply an obscenity, a depraved act by weak and miserable men, including all of us who have allowed it to go on and on with endless fury and destruction.", Author = "Noam Chomsky" },
